type Props = { used: number; limit: number };

export function UsageMeter({ used, limit }: Props) {
  const pct = Math.round((used / limit) * 100);
  return (
    <section data-testid="usage" className="p-card rounded-card bg-surface-raised border border-default shadow-raised flex flex-col gap-medium">
      <div className="flex items-center justify-between gap-small">
        <h2 className="text-heading font-bold text-primary">Usage</h2>
        <button type="button" data-testid="usage-refresh" className="h-control px-control rounded-control text-body font-medium bg-action-secondary hover:bg-action-secondary-hover text-primary border border-strong">
          <svg aria-hidden="true" viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor"><path d="M2 8a6 6 0 1 0 2-4.5M2 2v3h3" /></svg>
        </button>
      </div>
      <p data-testid="usage-value" className="text-lg text-primary">{used} of {limit} keys</p>
      <div role="progressbar" aria-label="Keys used" aria-valuenow={pct} aria-valuemin={0} aria-valuemax={100} className="w-full h-2 rounded-control bg-surface-sunken">
        <div data-testid="usage-fill" style={{ width: pct + "%" }} className="h-full rounded-control bg-action-primary" />
      </div>
    </section>
  );
}
